        tjw_rule_idgham_bila_ghunnah_notice: "استمع لـ 'هُدًى لِّلْمُتَّقِينَ' — هل تسمع اندماجاً سريعاً بلا أي أثر لغنة؟",

        tjw_rule_iqlab_name: "الإقلاب",
