        mr_note_m02: "Warm greetings, dear parent of {name}! Here's what he achieved this month, by God's grace 🌸 <j>His memorization grew by {ayat} new ayah(s), congratulations to him! 🌿</j> <h>On homework he showed lovely commitment across {hw} assignment(s), averaging {hwAvg}% 👏</h> <g>He attended {games} evaluation session(s), averaging {gameAvg}% — encouraging performance 🌟</g> <d>In dual tests his record was {w} win(s), {l} loss(es) and {t} tie(s) 💪</d> <e>He also moved past {errs} of his earlier mistake(s) ✨</e> <m>He is now at {scope} on his memorization path — we ask God to keep him steadfast.</m> Jazakallahu khayran, {name} — we're with you every step of the way 🤍",
        mr_note_m02_f: "Warm greetings, dear parent of {name}! Here's what she achieved this month, by God's grace 🌸 <j>Her memorization grew by {ayat} new ayah(s), congratulations to her! 🌿</j> <h>On homework she showed lovely commitment across {hw} assignment(s), averaging {hwAvg}% 👏</h> <g>She attended {games} evaluation session(s), averaging {gameAvg}% — encouraging performance 🌟</g> <d>In dual tests her record was {w} win(s), {l} loss(es) and {t} tie(s) 💪</d> <e>She also moved past {errs} of her earlier mistake(s) ✨</e> <m>She is now at {scope} on her memorization path — we ask God to keep her steadfast.</m> Jazakallahu khayran, {name} — we're with you every step of the way 🤍",
        mr_note_m03: "Peace be upon you, dear parent of {name}, here's a quick look at your child's journey this month 🌿 <j>By God's grace, he memorized {ayat} new ayah(s), and his steps are getting steadier 🌱</j> <e>He worked through {errs} of his earlier mistake(s), a sign of real perseverance ✨</e> <h>He completed {hw} homework assignment(s) averaging {hwAvg}%, and that makes us happy 👏</h> <g>He took part in {games} game-room evaluation session(s), averaging {gameAvg}% 🌟</g> <d>He also played dual tests: {w} win(s), {l} loss(es), {t} tie(s) 💪</d> <m>His memorization is now at: {scope}.</m> May God make you among the people of the Qur'an, {name}, and keep you steadfast 🌙",
        mr_note_m03_f: "Peace be upon you, dear parent of {name}, here's a quick look at your child's journey this month 🌿 <j>By God's grace, she memorized {ayat} new ayah(s), and her steps are getting steadier 🌱</j> <e>She worked through {errs} of her earlier mistake(s), a sign of real perseverance ✨</e> <h>She completed {hw} homework assignment(s) averaging {hwAvg}%, and that makes us happy 👏</h> <g>She took part in {games} game-room evaluation session(s), averaging {gameAvg}% 🌟</g> <d>She also played dual tests: {w} win(s), {l} loss(es), {t} tie(s) 💪</d> <m>Her memorization is now at: {scope}.</m> May God make you among the people of the Qur'an, {name}, and keep you steadfast 🌙",
