        mr_note_m05: "Welcome, dear parent of {name}, and thank you for following up — here is this month's summary 🌸 <j>{name} added {ayat} new ayah(s) to his memorization, and we ask God to make them firm 🌱</j> <g>His presence in the game room was good: {games} evaluation session(s), averaging {gameAvg}% 🌟</g> <h>On homework he stayed committed to {hw} assignment(s), averaging {hwAvg}% 👏</h> <d>In dual tests: {w} win(s), {l} loss(es), {t} tie(s) 💪</d> <e>A lovely achievement: he moved past {errs} of his old weak spot(s) ✨</e> <m>Keep going, champ — you are now at: {scope} 🌟</m> May God keep you steadfast, {name}, and increase your drive 🤍",
        mr_note_m05_f: "Welcome, dear parent of {name}, and thank you for following up — here is this month's summary 🌸 <j>{name} added {ayat} new ayah(s) to her memorization, and we ask God to make them firm 🌱</j> <g>Her presence in the game room was good: {games} evaluation session(s), averaging {gameAvg}% 🌟</g> <h>On homework she stayed committed to {hw} assignment(s), averaging {hwAvg}% 👏</h> <d>In dual tests: {w} win(s), {l} loss(es), {t} tie(s) 💪</d> <e>A lovely achievement: she moved past {errs} of her old weak spot(s) ✨</e> <m>Keep going, champ — you are now at: {scope} 🌟</m> May God keep you steadfast, {name}, and increase your drive 🤍",
