        mr_note_m07: "Peace be upon you, dear parent of {name} — a new month and a new achievement, in shaa Allah 🌿 <j>Mashallah, his memorization grew by {ayat} new ayah(s) this month 🌱</j> <h>He didn't slack on homework — he completed {hw} assignment(s) averaging {hwAvg}% 👏</h> <d>He took on dual tests with a great spirit: {w} win(s), {l} loss(es), {t} tie(s) — every round brings him closer to mastery 💪</d> <g>He attended {games} game-room evaluation session(s), averaging {gameAvg}% 🌟</g> <e>He moved past {errs} of his earlier weak spot(s) ✨</e> <m>His memorization is currently at: {scope}.</m> May God increase you in knowledge and drive, {name} 🌙",
